// =========================================================
// Reset password — reads ?token= from the URL (from the email link
// generated by POST /auth/forgot-password) and calls POST /auth/reset-password.
// =========================================================

const resetForm = document.getElementById("reset-form");
if (resetForm) {
  const token = new URLSearchParams(window.location.search).get("token");

  resetForm.addEventListener("submit", async (e) => {
    e.preventDefault();
    const msg = document.getElementById("form-msg");
    const btn = document.getElementById("reset-btn");

    if (!token) return showMsg(msg, "This reset link is invalid or missing a token.", "error");

    const password = document.getElementById("password").value;
    const confirm = document.getElementById("confirm_password").value;

    if (password.length < 8) return showMsg(msg, "Password must be at least 8 characters.", "error");
    if (password !== confirm) return showMsg(msg, "Passwords do not match.", "error");

    setLoading(btn, true, "Update Password");
    try {
      await apiFetch("/auth/reset-password", { method: "POST", body: { token, new_password: password } });
      showMsg(msg, "Password updated. Redirecting to login…", "success");
      setTimeout(() => { window.location.href = "login.html"; }, 1500);
    } catch (err) {
      showMsg(msg, err.message, "error");
      setLoading(btn, false, "Update Password");
    }
  });
}
